const q = new URLSearchParams(location.search);
const btn = document.getElementById('cta');
const url = new URL(btn.href);
url.searchParams.set('sub1', q.get('utm_campaign') || 'none');
url.searchParams.set('sub2', q.get('utm_content') || 'none');
url.searchParams.set('sub4', q.get('cid') || 'none');
btn.href = url.toString();
